<script setup lang="ts">
import {reactive} from 'vue'
import {useRoute,useRouter} from 'vue-router'
import {useQualityList} from '../hooks/useQualityList'
import {orderStates,time} from '../../../shared/types'
const vm=reactive(useQualityList()),route=useRoute(),router=useRouter(),modes=[{value:'inspect',label:'待核查'},{value:'rectify',label:'待整改'},{value:'review',label:'待复验'},{value:'completed',label:'已完成'},{value:'related',label:'历史'}]
</script><template><section class="page"><div class="list-filters"><a-select :value="String(route.query.mode||'inspect')" :options="modes" @change="(v:unknown)=>router.replace('/orders?mode='+v)" /><a-select v-model:value="vm.projectId" :options="vm.projects.map(p=>({value:p.id,label:p.name}))" placeholder="全部项目" allow-clear /><a-button :loading="vm.loading" @click="vm.load">刷新</a-button></div><a-alert v-if="vm.error" :message="vm.error" type="error" show-icon /><a-spin :spinning="vm.loading"><a-empty v-if="!vm.loading&&!vm.rows.length" description="暂无核查记录" /><a-card v-for="order in vm.rows" :key="order.id" style="margin-bottom:12px" :title="order.taskName"><template #extra><a-tag color="blue">{{orderStates[order.workOrderStatus]}}</a-tag></template><p>{{order.projectName}}</p><p>回传时限：{{time(order.reportDeadline)}}</p><p>{{order.recordCount}} 项检查 · 得分 {{order.totalScore??'—'}}</p><a-button type="primary" block @click="router.push('/orders/'+order.id)">查看 / 处理</a-button></a-card></a-spin><a-pagination v-if="vm.total" v-model:current="vm.current" :total="vm.total" :page-size="10" simple @change="vm.load" /></section></template>
